import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { lstat, readFile, readdir, realpath } from 'node:fs/promises';
import path from 'node:path';

const hash = (kind, bytes) => createHash(kind).update(bytes).digest('hex');
const sha40 = value => typeof value === 'string' && /^[a-f0-9]{40}$/.test(value);

// Test evidence only. A selected, externally pinned manifest must verify every
// source byte; its base commit is never presented as a full checkout HEAD.
export async function harnessSourceIdentity({ cwd = process.cwd(), manifestPath, manifestSha256 } = {}) {
  if (manifestPath === undefined && manifestSha256 === undefined) {
    const commit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd, encoding: 'utf8' }).trim();
    assert.ok(sha40(commit), 'Expected an actual Git HEAD');
    return { sourceCommit: commit, sourceIdentity: { kind: 'git-checkout', commit } };
  }
  assert.ok(path.isAbsolute(manifestPath || '') && /^[a-f0-9]{64}$/.test(manifestSha256 || ''), 'Explicit absolute manifest and expected SHA256 required');
  assert.equal(await realpath(manifestPath), manifestPath, 'Manifest symlinks are not accepted');
  const manifestInfo = await lstat(manifestPath);
  assert.ok(manifestInfo.isFile() && manifestInfo.size <= 4 * 1024 * 1024, 'Bounded regular manifest required');
  const raw = await readFile(manifestPath);
  assert.equal(hash('sha256', raw), manifestSha256, 'Manifest SHA256 mismatch');
  const manifest = JSON.parse(raw), source = path.resolve(cwd);
  assert.equal(await realpath(source), source, 'Source directory symlinks are not accepted');
  assert.equal(manifest.schema, 'workspace.source-acceptance-manifest.v1');
  assert.ok(sha40(manifest.commit) && Array.isArray(manifest.appliedCommits) && manifest.appliedCommits.every(sha40), 'Exact base and applied commits required');
  assert.ok(Array.isArray(manifest.files) && manifest.files.length > 0, 'Full source-file manifest required');
  const expected = new Set();
  for (const row of manifest.files) {
    const name = row.path, parts = typeof name === 'string' ? name.split('/') : [];
    assert.ok(parts.length && parts.every(part => part && part !== '.' && part !== '..') && !name.includes('\\') && !name.includes('\0')
      && !path.posix.isAbsolute(name) && !['node_modules', 'dist'].includes(parts[0]) && !expected.has(name), 'Invalid or duplicate source path');
    expected.add(name);
    assert.ok(Number.isSafeInteger(row.bytes) && row.bytes >= 0 && /^[a-f0-9]{64}$/.test(row.sha256) && sha40(row.gitBlobSha1), 'Invalid source-file identity');
    const file = path.join(source, ...parts), info = await lstat(file);
    assert.ok(info.isFile() && !info.isSymbolicLink(), 'Regular source file required: ' + name);
    assert.equal(await realpath(file), file, 'Source symlinks are not accepted: ' + name);
    const bytes = await readFile(file);
    assert.equal(bytes.length, row.bytes, 'Source size mismatch: ' + name);
    assert.equal(hash('sha256', bytes), row.sha256, 'Source SHA256 mismatch: ' + name);
    assert.equal(hash('sha1', Buffer.concat([Buffer.from(`blob ${bytes.length}\0`), bytes])), row.gitBlobSha1, 'Git blob mismatch: ' + name);
  }
  const actual = new Set();
  async function walk(directory, prefix = '') {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      // Dependencies are separately pinned by the acceptance runner. dist is
      // generated by the original build and separately hashed in UI evidence.
      if (!prefix && entry.name === 'node_modules' && (entry.isDirectory() || entry.isSymbolicLink())) continue;
      if (!prefix && entry.name === 'dist' && entry.isDirectory()) continue;
      const name = prefix + entry.name;
      assert.ok(!entry.isSymbolicLink(), 'Unexpected source symlink: ' + name);
      if (entry.isDirectory()) await walk(path.join(directory, entry.name), name + '/');
      else { assert.ok(entry.isFile(), 'Unexpected source file type: ' + name); actual.add(name); }
    }
  }
  await walk(source);
  assert.deepEqual([...actual].sort(), [...expected].sort(), 'Unexpected or missing source files');
  return { sourceCommit: null, sourceIdentity: { kind: 'verified-source-subset', baseCommit: manifest.commit,
    appliedCommits: [...manifest.appliedCommits], manifestSha256, fileCount: expected.size, fullGitTree: false } };
}
